40. ///
41. /// # Description
42. ///
43. /// A type that represents a page directory.
44. ///
45. pub struct PageDirectory<T: DerefMut<Target = [PteWord]>> {
46.     /// Entries.
47.     entries: T,
48. }
49. 
50. //==================================================================================================
51. // Implementations
52. //==================================================================================================
53. 
54. impl<T: DerefMut<Target = [PteWord]>> PageDirectory<T> {
55.     pub fn new(entries: T) -> Self {
56.         let mut pgdir: PageDirectory<T> = PageDirectory { entries };
57.         pgdir.clean();
58.         pgdir
59.     }
60. 
61.     pub fn map(
62.         &mut self,
63.         vaddr: PageTableAddress,
64.         paddr: FrameAddress,
65.         supervisor: bool,
66.         access: AccessPermission,
67.     ) -> Result<(), Error> {
68.         // Obtain a cached copy of the page directory entry.
69.         let pde: PageDirectoryEntry = match self.read_pde(vaddr) {
70.             Some(pde) => pde,
71.             None => {
72.                 let reason: &str = "failed to read page directory entry";
73.                 error!("{reason}");
74.                 return Err(Error::new(ErrorCode::TryAgain, reason));
75.             },
76.         };
77. 
78.         // Check if page directory entry is busy.
79.         if pde.is_present() {
80.             let reason: &str = "page directory entry is busy";
81.             error!("{reason}");
82.             return Err(Error::new(ErrorCode::ResourceBusy, reason));
83.         }
84. 
85.         // Construct page directory entry
86.         let pde: PageDirectoryEntry = PageDirectoryEntry::new(
87.             PageDirectoryEntryFlags::new(
88.                 PresentFlag::Present,
89.                 if access.is_writable() {
90.                     ReadWriteFlag::ReadWrite
91.                 } else {
92.                     ReadWriteFlag::ReadOnly
93.                 },
94.                 if supervisor {
95.                     UserSupervisorFlag::Supervisor
96.                 } else {
97.                     UserSupervisorFlag::User
98.                 },
99.                 PageWriteThroughFlag::NotWriteThrough,
100.                 PageCacheDisableFlag::CacheEnabled,
101.                 AccessedFlag::NotAccessed,
102.                 DirtyFlag::NotDirty,
103.                 PageSizeFlag::Standard,
104.             ),
105.             paddr.into_frame_number(),
106.         );
107. 
108.         // Write page directory entry
109.         self.write_pde(vaddr, pde);
110. 
111.         Ok(())
112.     }
113. 
114.     ///
115.     /// # Description
116.     ///
117.     /// Unmaps a page from the page directory.
118.     ///
119.     /// # Parameters
120.     ///
121.     /// - `pgtable_address`: Page table address.
122.     ///
123.     /// # Returns
124.     ///
125.     /// Upon successful completion, `Ok(())` is returned. Upon failure, an error is returned
126.     /// instead.
127.     ///
128.     pub fn unmap(&mut self, pgtable_address: PageTableAddress) -> Result<FrameAddress, Error> {
129.         // Obtain a cached copy of the page directory entry.
130.         let pde: PageDirectoryEntry = match self.read_pde(pgtable_address) {
131.             Some(pde) => pde,
132.             None => {
133.                 let reason: &str = "failed to read page directory entry";
134.                 error!("{reason}");
135.                 return Err(Error::new(ErrorCode::TryAgain, reason));
136.             },
137.         };
138. 
139.         // Check if page directory entry is present.
140.         if !pde.is_present() {
141.             let reason: &str = "page directory entry is not present";
142.             error!("{reason}");
143.             return Err(Error::new(ErrorCode::ResourceBusy, reason));
144.         }
145. 
146.         // Retrieve frame address.
147.         let paddr: FrameAddress = FrameAddress::from_frame_number(pde.frame_number())?;
148. 
149.         // Construct page directory entry.
150.         let pde: PageDirectoryEntry = PageDirectoryEntry::new(
151.             PageDirectoryEntryFlags::new(
152.                 PresentFlag::NotPresent,
153.                 ReadWriteFlag::ReadOnly,
154.                 UserSupervisorFlag::User,
155.                 PageWriteThroughFlag::WriteThrough,
156.                 PageCacheDisableFlag::CacheDisabled,
157.                 AccessedFlag::NotAccessed,
158.                 DirtyFlag::NotDirty,
159.                 PageSizeFlag::Standard,
160.             ),
161.             FrameNumber::NULL,
162.         );
163. 
164.         // Write page directory entry.
165.         self.write_pde(pgtable_address, pde);
166. 
167.         // Invalidate the TLB entry for this page table range so the CPU does not use a
168.         // stale PDE pointing to the freed page table.
169.         // SAFETY: called from kernel mode after modifying a PDE.
170.         unsafe { ::arch::mem::paging::invlpg(pgtable_address.into_raw_value()) };
171. 
172.         Ok(paddr)
173.     }
174. 
175.     fn clean(&mut self) {
176.         for pde in self.entries.iter_mut() {
177.             *pde = 0;
178.         }
179.     }
180. 
181.     pub fn read_pde(&self, vaddr: PageTableAddress) -> Option<PageDirectoryEntry> {
182.         let pde_idx: usize = vaddr.get_pde_index();
183.         PageDirectoryEntry::from_raw_value(self.entries[pde_idx])
184.     }
185. 
186.     fn write_pde(&mut self, vaddr: PageTableAddress, pde: PageDirectoryEntry) {
187.         let pde_idx: usize = vaddr.get_pde_index();
188.         self.entries[pde_idx] = pde.into_raw_value();
189.     }
190. 
191.     pub fn physical_address(&self) -> Result<FrameAddress, Error> {
192.         let vaddr: usize = self.entries.as_ptr() as usize;
193.         let paddr: usize = crate::hal::platform::virt_to_phys(vaddr);
194.         Ok(FrameAddress::new(PageAligned::from_address(PhysicalAddress::from_raw_value(paddr)?)?))
195.     }
196. }
